export const getNodesNodeIdAddonsProviderIndexRoute = createRoute({
  method: 'get',
  path: '/nodes/{node_id}/addons/{provider}/',
  tags: ['Nodes'],
  summary: 'Retrieve an addon',
  description:
    'Retrieve details of an individual addon connected to this node.\n#### Permissions\nNodeSettings that are attached to public nodes will give read-only access to everyone. Private nodes require explicit read permission. Write and admin access are the same for public and private nodes. Administrators on a parent node have implicit read permissions for all child nodes.\nAny users with write or admin access to the node are able to deauthorize an enabled addon, but only the addon authorizer is able to change the configuration (i.e. selected folder) of an already-configured NodeSettings entity.\n#### Returns\nReturns a JSON object with a `data` key containing the details of the requested addon, if the request is successful.\n\nIf the request is unsuccessful, an `errors` key containing information about the failure will be returned. Refer to the [list of error codes](#tag/Errors-and-Error-Codes) to understand why this request may have failed.',
  operationId: 'nodes_addon_read',
  request: {
    params: z.object({
      node_id: z
        .string()
        .openapi({
          param: {
            description: 'The unique identifier of the node.',
            in: 'path',
            name: 'node_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
      provider: z
        .string()
        .openapi({
          param: {
            description: 'The unique identifier of the addon.',
            in: 'path',
            name: 'provider',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        '*/*': {
          schema: z
            .object({
              attributes: z
                .object({
                  configured: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'Whether or not this node has been configured with an addon folder.',
                      readOnly: true,
                    }),
                  enabled: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'Whether or not this node has a NodeSettings object associated with it.',
                      readOnly: true,
                    }),
                  external_account_id: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'The ID of the associated node addon account, if any.',
                      readOnly: true,
                    }),
                  folder_id: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'The ID of the linked folder from the addon provider.',
                      readOnly: true,
                    }),
                  folder_path: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'The folder path of the linked folder from the addon provider. Google Drive specific',
                      readOnly: true,
                    }),
                  label: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'A label specific to the addon provider.',
                      readOnly: true,
                    }),
                  node_has_auth: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'Whether or not this node is fully authorized to use this node addon.',
                      readOnly: true,
                    }),
                  url: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'An external link specific to the addon provider.',
                      readOnly: true,
                    }),
                })
                .exactOptional()
                .openapi({
                  description: 'The properties of the node addon entity.',
                  readOnly: true,
                  title: 'Attributes',
                  required: [],
                }),
              id: z
                .string()
                .openapi({
                  description: 'The unique identifier of the draft registration entity.',
                  readOnly: true,
                }),
              links: z
                .object({
                  self: z
                    .string()
                    .openapi({
                      description: 'A link to the the canonical API endpoint for this node addon.',
                      readOnly: true,
                    }),
                })
                .exactOptional()
                .openapi({
                  description: 'URLs to alternative representations of the node addon entity.',
                  readOnly: true,
                  required: ['self'],
                  title: 'Links',
                }),
              type: z
                .string()
                .openapi({
                  description: 'The type identifier of the node addon entity (`node_addons`).',
                  readOnly: true,
                }),
            })
            .openapi({ required: ['id', 'type'], title: 'Node Addon' }),
        },
      },
    },
  },
})

export const patchNodesNodeIdAddonsProviderIndexRoute = createRoute({
  method: 'patch',
  path: '/nodes/{node_id}/addons/{provider}/',
  tags: ['Nodes'],
  summary: 'Update an addon',
  description:
    'Updates a node addon by setting the values of the attributes specified in the request body. Any unspecified attributes will be left unchanged.\n\nNode addon can be updated with either a **PUT** or **PATCH** request. The `external_account_id`, `enabled`, and `folder_id` fields are mandatory in a **PUT**, and optional in **PATCH**. Non-string values will be accepted and stringified, however we make no promises about the stringification output.\n\nTo delete or deauthorize a node addon, issue a **PUT** with all fields set to `null` or `False`, or a **PATCH** with enabled set `False`.\n#### Permissions\nNodeSettings that are attached to public nodes will give read-only access to everyone. Private nodes require explicit read permission. Write and admin access are the same for public and private nodes. Administrators on a parent node have implicit read permissions for all child nodes.\nAny users with write or admin access to the node are able to deauthorize an enabled addon, but only the addon authorizer is able to change the configuration (i.e. selected folder) of an already-configured NodeSettings entity.\n\n#### Returns\nReturns a JSON object with a `data` key containing the new representation of the updated node addon, if the request is successful.\n\nIf the request is unsuccessful, an `errors` key containing information about the failure will be returned. Refer to the [list of error codes](#tag/Errors-and-Error-Codes) to understand why this request may have failed.',
  operationId: 'nodes_node_addon_update',
  request: {
    params: z.object({
      node_id: z
        .string()
        .openapi({
          param: {
            description: 'The unique identifier of the node.',
            in: 'path',
            name: 'node_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
      provider: z
        .string()
        .openapi({
          param: {
            description: 'The unique identifier of the addon.',
            in: 'path',
            name: 'provider',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({})
            .openapi({
              example: {
                data: {
                  attributes: {
                    external_account_id: '{account_id}',
                    folder_id: '{folder_id}',
                    folder_path: '{folder_path}',
                    label: '{label}',
                    url: '{url}',
                  },
                  id: '{provider}',
                  type: 'node_addons',
                },
              },
            }),
        },
      },
      required: true,
    },
  },
  responses: { 200: { description: 'OK' } },
})

