export const getNodesNodeIdCommentsIndexRoute = createRoute({
  method: 'get',
  path: '/nodes/{node_id}/comments/',
  tags: ['Nodes'],
  summary: 'List all comments',
  description:
    '\nA paginated list of comments related to a given node.\n\nThe returned comments are sorted by their creation date, with the most recent comments appearing first.\n#### Permissions\nComments on public nodes are given read-only access to everyone.\n\nIf the node comment-level is `private`, only contributors have permission to comment.\n\nIf the comment-level is `public`, any logged-in OSF user can comment.\n\nComments on private nodes are only visible to contributors and administrators on the parent node.\n#### Returns\nReturns a JSON object containing `data` and `links` keys.\n\nThe `data` key contains an array of comment objects. Each resource in the array is a separate comment object.\n\nThe `links` key contains a dictionary of links that can be used for [pagination](#tag/Pagination).\n#### Filtering\nYou can optionally request that the response only include comments that match your filters by utilizing the `filter` query parameter, e.g. https://api.osf.io/v2/nodes/ezcuj/comments/?filter[target_id]=jg7sezmdnt93\n\nNodes may be filtered by their `deleted`, `target_id`, `date_created`, `date_modified`.\n\nMost fields are string fields and will be filtered using simple substring matching. Public and preprint are boolean fields, and can be filtered using truthy values, such as **true**, **false**, **0** or **1**. Note that quoting `true` or `false` in the query will cause the match to fail.',
  operationId: 'nodes_comments_list',
  request: {
    params: z.object({
      node_id: z
        .string()
        .openapi({
          param: {
            description: 'The unique identifier of the node.',
            in: 'path',
            name: 'node_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        '*/*': {
          schema: z.array(
            z
              .object({
                attributes: z
                  .object({
                    can_edit: z
                      .boolean()
                      .exactOptional()
                      .openapi({
                        description:
                          'Whether or not the current user has permission to edit this comment',
                        readOnly: true,
                      }),
                    content: z
                      .string()
                      .exactOptional()
                      .openapi({ description: 'The content of the comment.', readOnly: false }),
                    date_created: z.iso
                      .datetime({ offset: true })
                      .exactOptional()
                      .openapi({
                        description:
                          'The time at which the comment was created, as an iso8601 formatted timestamp.',
                        readOnly: true,
                      }),
                    date_modified: z.iso
                      .datetime({ offset: true })
                      .exactOptional()
                      .openapi({
                        description:
                          'The time at which the comment was last modified, as an iso8601 formatted timestamp.',
                        readOnly: true,
                      }),
                    deleted: z
                      .boolean()
                      .exactOptional()
                      .openapi({
                        description: 'Whether or not the comment is deleted.',
                        readOnly: true,
                      }),
                    has_children: z
                      .boolean()
                      .exactOptional()
                      .openapi({
                        description: 'Whether or not the comment has replies.',
                        readOnly: true,
                      }),
                    has_report: z
                      .boolean()
                      .exactOptional()
                      .openapi({
                        description:
                          'Whether or not the comment the current user reported this as spam.',
                        readOnly: true,
                      }),
                    is_abuse: z
                      .boolean()
                      .exactOptional()
                      .openapi({
                        description: 'Whether or not the comment is flagged or confirmed spam.',
                        readOnly: true,
                      }),
                    is_ham: z
                      .boolean()
                      .exactOptional()
                      .openapi({
                        description:
                          'Whether or not an admin checked the legitimacy of this comment.',
                        readOnly: true,
                      }),
                    modified: z
                      .boolean()
                      .exactOptional()
                      .openapi({
                        description: 'Whether or not the comment has been edited.',
                        readOnly: true,
                      }),
                    page: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          'The page type the comment is on, e.g. `node`, `registration`, `wiki`, `files`.',
                        readOnly: true,
                      }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'The properties of the comment entity.',
                    readOnly: false,
                    title: 'Attributes',
                    required: [],
                  }),
                id: z
                  .string()
                  .openapi({
                    description: 'The identifier of the comment entity.',
                    readOnly: true,
                  }),
                links: z
                  .object({
                    self: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A link to the detail page for the comment.',
                        readOnly: true,
                      }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'URLs to alternative representations of the comment entity.',
                    readOnly: true,
                    title: 'Links',
                    required: [],
                  }),
                relationships: z
                  .object({
                    node: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A relationship to the node the comment is on.',
                        readOnly: true,
                      }),
                    replies: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A relationship to the replies to the comment.',
                        readOnly: true,
                      }),
                    reports: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A relationship to the reports connected to the comment.',
                        readOnly: true,
                      }),
                    target: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A relationship to the target of the comment.',
                        readOnly: true,
                      }),
                    user: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A relationship to the user who created the comment.',
                        readOnly: true,
                      }),
                  })
                  .exactOptional()
                  .openapi({
                    description:
                      'URLs to other entities or entity collections that have a relationship to the comment entity.',
                    readOnly: false,
                    title: 'Relationships',
                    required: [],
                  }),
                type: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'The type identifier of the comment entity (`comments`).',
                    readOnly: true,
                  }),
              })
              .openapi({
                example: {
                  data: {
                    attributes: { content: 'comment content' },
                    relationships: {
                      target: { data: { id: '{target_id}', type: '{target_type}' } },
                    },
                    type: 'comments',
                  },
                },
                required: ['id'],
                title: 'Comment',
              }),
          ),
        },
      },
    },
  },
})

