export const getNodesNodeIdViewOnlyLinksIndexRoute = createRoute({
  method: 'get',
  path: '/nodes/{node_id}/view_only_links/',
  tags: ['Nodes'],
  summary: 'List all view only links',
  description:
    "List of view only links on a node.\n#### Returns\nReturns a JSON object containing `data` and `links` keys.\n\nThe `data` key contains an array of up to 10 view only links. Each resource in the array is a view only link object.\n\nThe `links` key contains a dictionary of links that can be used for [pagination](#tag/Pagination).\n\n#### Permissions\n\nView only links on a node, public or private, are readable and writeable only by users that are administrators on the node.\n\n#### Filtering\n\nYou can optionally request that the response only include view only links that match your filters by utilizing the `filter` query parameter, e.g. https://api.osf.io/v2/nodes/ezcuj/view_only_links/?filter[anonymous]=true.\n\nView Only Links may be filtered based on their `name`, `anonymous` and `date_created` fields. Possible comparison operators include 'gt' (greater than), 'gte'(greater than or equal to), 'lt' (less than) and 'lte' (less than or equal to). The date must be in the format YYYY-MM-DD and the time is optional.",
  operationId: 'nodes_view_only_links_list',
  request: {
    params: z.object({
      node_id: z
        .string()
        .openapi({
          param: {
            description: 'The unique identifier of the node.',
            in: 'path',
            name: 'node_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        '*/*': {
          schema: z.array(
            z
              .object({
                attributes: z
                  .object({
                    anonymous: z
                      .boolean()
                      .default(true)
                      .exactOptional()
                      .openapi({
                        description:
                          'Whether or not the view only link has anonymized contributors',
                        readOnly: false,
                      }),
                    date_created: z.iso
                      .datetime({ offset: true })
                      .exactOptional()
                      .openapi({
                        description:
                          'The time at which the view only link was created, as an iso8601 formatted timestamp.',
                        readOnly: true,
                      }),
                    key: z
                      .string()
                      .exactOptional()
                      .openapi({ description: 'The view only key', readOnly: true }),
                    name: z
                      .string()
                      .default('Shared project link')
                      .exactOptional()
                      .openapi({ description: 'The name of the view only link', readOnly: false }),
                  })
                  .openapi({
                    description: 'The properties of the view only link entity.',
                    readOnly: true,
                    title: 'Attributes',
                    required: [],
                  }),
                id: z
                  .string()
                  .openapi({
                    description: 'The unique identifier of the view only link.',
                    readOnly: true,
                  }),
                relationships: z
                  .object({
                    creator: z
                      .string()
                      .openapi({
                        description: 'A relationship to the user who created this view only link.',
                        readOnly: true,
                      }),
                    nodes: z
                      .string()
                      .openapi({
                        description:
                          'A relationship to the nodes which this view only link gives read-only access to.',
                        readOnly: false,
                      }),
                  })
                  .openapi({
                    description:
                      'URLs to other entities or entity collections that have a relationship to the view only link entity.',
                    readOnly: true,
                    required: ['nodes', 'creator'],
                    title: 'Relationships',
                  }),
                type: z
                  .string()
                  .openapi({
                    description: "The type identifier of the view only link ('view-only-links').",
                    readOnly: true,
                  }),
              })
              .openapi({
                required: ['id', 'type', 'attributes', 'relationships'],
                title: 'view-only-links',
              }),
          ),
        },
      },
    },
  },
})

