export const getNodesNodeIdWikisIndexRoute = createRoute({
  method: 'get',
  path: '/nodes/{node_id}/wikis/',
  tags: ['Nodes'],
  summary: 'List all wikis',
  description:
    "List of wiki pages on a node.\n#### Returns\nPaginated list of the node's current wiki page versions ordered by their date_modified. Each resource contains the full representation of the wiki, meaning additional requests to an individual wiki's detail view are not necessary.\n\nNote that if an anonymous view_only key is being used, the user relationship will not be exposed.\n\nIf the request is unsuccessful, a JSON object with an `errors` key containing information about the failure will be returned. Refer to the [list of error codes](#tag/Errors-and-Error-Codes) to understand why this request may have failed.\n#### Filtering\nWiki pages can be filtered based on their `name` and `date_modified` fields.\n+ `filter[name]=<Str>` -- filter wiki pages by name\n+ `filter[date_modified][comparison_operator]=YYYY-MM-DDTH:M:S` -- filter wiki pages based on date modified.\n\nPossible comparison operators include 'gt' (greater than), 'gte'(greater than or equal to), 'lt' (less than) and 'lte' (less than or equal to). The date must be in the format YYYY-MM-DD and the time is optional.",
  operationId: 'nodes_wikis_list',
  request: {
    params: z.object({
      node_id: z
        .string()
        .openapi({
          param: {
            description: 'The unique identifier of the node.',
            in: 'path',
            name: 'node_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        '*/*': {
          schema: z.array(
            z
              .object({
                attributes: z
                  .object({
                    content_type: z
                      .string()
                      .openapi({
                        description: 'Content type of the wiki (`text/markdown`).',
                        readOnly: true,
                      }),
                    current_user_can_comment: z
                      .string()
                      .openapi({
                        description:
                          'Whether the current user is allowed to post comments on this wiki.',
                        readOnly: true,
                      }),
                    date_modified: z.iso
                      .datetime({ offset: true })
                      .openapi({
                        description:
                          'The date and time at which the wiki was last modified, as an iso8601 formatted timestamp.',
                        readOnly: true,
                      }),
                    extra: z
                      .string()
                      .openapi({
                        description:
                          'A dictionary containing additional metadata about this wiki, including version information.',
                        readOnly: true,
                      }),
                    kind: z
                      .string()
                      .openapi({ description: 'The type of object.', readOnly: true }),
                    materialized_path: z
                      .string()
                      .openapi({
                        description: 'Materialized path to the wiki object.',
                        readOnly: true,
                      }),
                    name: z
                      .string()
                      .openapi({ description: 'The name/title of the wiki page.', readOnly: true }),
                    path: z
                      .string()
                      .openapi({ description: 'Path to the wiki object.', readOnly: true }),
                    size: z.string().openapi({ description: 'Size of the wiki.', readOnly: true }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'The properties of the wiki.',
                    readOnly: false,
                    required: [
                      'kind',
                      'name',
                      'date_modified',
                      'extra',
                      'content_type',
                      'path',
                      'current_user_can_comment',
                      'materialized_path',
                      'size',
                    ],
                    title: 'Attributes',
                  }),
                id: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The identifier of the wiki.', readOnly: true }),
                links: z
                  .object({
                    download: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'The URL to download the content of the wiki.',
                        readOnly: true,
                      }),
                    info: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A link to the detail page for the wiki.',
                        readOnly: true,
                      }),
                    self: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A link to the detail page for the wiki.',
                        readOnly: true,
                      }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'URLs to alternative representations of the wiki.',
                    readOnly: true,
                    title: 'Links',
                    required: [],
                  }),
                relationships: z
                  .object({
                    comments: z
                      .string()
                      .openapi({
                        description: 'A relationship to the comments related to this wiki.',
                        readOnly: false,
                      }),
                    node: z
                      .string()
                      .openapi({
                        description: 'A relationship to the associated node.',
                        readOnly: false,
                      }),
                    user: z
                      .string()
                      .openapi({
                        description: 'A relationship to the user associated with this wiki.',
                        readOnly: false,
                      }),
                  })
                  .openapi({
                    description:
                      'URLs to other entities or entity collections that have a relationship to the wiki.',
                    readOnly: false,
                    required: ['node', 'user', 'comments'],
                    title: 'Relationships',
                  }),
                type: z
                  .string()
                  .openapi({
                    description: 'The type identifier of the wiki (`wikis`).',
                    readOnly: false,
                  }),
              })
              .openapi({ required: ['type', 'relationships'], title: 'Wiki' }),
          ),
        },
      },
    },
  },
})

