export const getRegistrationsRegistrationIdWikisIndexRoute = createRoute({
  method: 'get',
  path: '/registrations/{registration_id}/wikis/',
  tags: ['Registrations'],
  summary: 'List all wikis',
  description:
    "A paginated list of the registration's wiki pages\n#### Returns\nA list of all registration's current wiki page versions ordered by their date_modified. Each resource contains the full representation of the wiki, meaning additional requests to an individual wiki's detail view are not necessary.\n\nIf the request is unsuccessful, a JSON object with an `errors` key containing information about the failure will be returned. Refer to the [list of error codes](#tag/Errors-and-Error-Codes) to understand why this request may have failed.\n#### Filtering\nWiki pages can be filtered based on their `name` and `date_modified` fields.\n+ `filter[name]=<Str>` -- filter wiki pages by name\n+ `filter[date_modified][comparison_operator]=YYYY-MM-DDTH:M:S` -- filter wiki pages based on date modified.\n\nPossible comparison operators include 'gt' (greater than), 'gte'(greater than or equal to), 'lt' (less than) and 'lte' (less than or equal to). The date must be in the format YYYY-MM-DD and the time is optional.",
  operationId: 'registrations_wikis_list',
  request: {
    params: z.object({
      registration_id: z
        .string()
        .openapi({
          param: {
            description: 'The unique identifier of the registration.',
            in: 'path',
            name: 'registration_id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        '*/*': {
          schema: z.array(
            z
              .object({
                attributes: z
                  .object({
                    content_type: z
                      .string()
                      .openapi({
                        description: 'Content type of the wiki (`text/markdown`).',
                        readOnly: true,
                      }),
                    current_user_can_comment: z
                      .string()
                      .openapi({
                        description:
                          'Whether the current user is allowed to post comments on this wiki.',
                        readOnly: true,
                      }),
                    date_modified: z.iso
                      .datetime({ offset: true })
                      .openapi({
                        description:
                          'The date and time at which the wiki was last modified, as an iso8601 formatted timestamp.',
                        readOnly: true,
                      }),
                    extra: z
                      .string()
                      .openapi({
                        description:
                          'A dictionary containing additional metadata about this wiki, including version information.',
                        readOnly: true,
                      }),
                    kind: z
                      .string()
                      .openapi({ description: 'The type of object.', readOnly: true }),
                    materialized_path: z
                      .string()
                      .openapi({
                        description: 'Materialized path to the wiki object.',
                        readOnly: true,
                      }),
                    name: z
                      .string()
                      .openapi({ description: 'The name/title of the wiki page.', readOnly: true }),
                    path: z
                      .string()
                      .openapi({ description: 'Path to the wiki object.', readOnly: true }),
                    size: z.string().openapi({ description: 'Size of the wiki.', readOnly: true }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'The properties of the wiki.',
                    readOnly: false,
                    required: [
                      'kind',
                      'name',
                      'date_modified',
                      'extra',
                      'content_type',
                      'path',
                      'current_user_can_comment',
                      'materialized_path',
                      'size',
                    ],
                    title: 'Attributes',
                  }),
                id: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The identifier of the wiki.', readOnly: true }),
                links: z
                  .object({
                    download: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'The URL to download the content of the wiki.',
                        readOnly: true,
                      }),
                    info: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A link to the detail page for the wiki.',
                        readOnly: true,
                      }),
                    self: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A link to the detail page for the wiki.',
                        readOnly: true,
                      }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'URLs to alternative representations of the wiki.',
                    readOnly: true,
                    title: 'Links',
                    required: [],
                  }),
                relationships: z
                  .object({
                    comments: z
                      .string()
                      .openapi({
                        description: 'A relationship to the comments related to this wiki.',
                        readOnly: false,
                      }),
                    node: z
                      .string()
                      .openapi({
                        description: 'A relationship to the associated node.',
                        readOnly: false,
                      }),
                    user: z
                      .string()
                      .openapi({
                        description: 'A relationship to the user associated with this wiki.',
                        readOnly: false,
                      }),
                  })
                  .openapi({
                    description:
                      'URLs to other entities or entity collections that have a relationship to the wiki.',
                    readOnly: false,
                    required: ['node', 'user', 'comments'],
                    title: 'Relationships',
                  }),
                type: z
                  .string()
                  .openapi({
                    description: 'The type identifier of the wiki (`wikis`).',
                    readOnly: false,
                  }),
              })
              .openapi({ required: ['type', 'relationships'], title: 'Wiki' }),
          ),
        },
      },
    },
  },
})

export const getSchemaResponsesIndexRoute = createRoute({
  method: 'get',
  path: '/schema_responses/',
  tags: ['Schema Responses'],
  summary: 'List all Schema Responses',
  description:
    'This retrieves a paginated list of all active Schema Responses that are public.\n#### Returns\nReturns a JSON object containing `data` and `links` keys. The `data` key contains an array of 10 Schema Responses. Each resource in the array is a separate Registration Schemas object. The `links` key contains a dictionary of links that can be used for [pagination](#tag/Pagination).\n#### Errors\nThis request should never return an error.',
  operationId: 'schema_responses_list',
  responses: {
    200: {
      description: 'OK',
      content: {
        '*/*': {
          schema: z
            .object({
              attributes: z
                .object({
                  date_created: z
                    .int()
                    .exactOptional()
                    .openapi({
                      description: 'The date the Schema Response was created',
                      readOnly: false,
                    }),
                  date_modified: z
                    .int()
                    .exactOptional()
                    .openapi({
                      description: 'The date the Schema Response was most recently changed.',
                      readOnly: false,
                    }),
                  date_submitted: z
                    .int()
                    .exactOptional()
                    .openapi({
                      description: 'The date the Schema Response was submitted for approval.',
                      readOnly: false,
                    }),
                  is_original_response: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'A bool that represents whether the Schema Response is the original one that was made when the registration was created.',
                      readOnly: false,
                    }),
                  is_pending_current_user_approval: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'A bool that represents whether the Schema Response needs the current user to approve the state transition.',
                      readOnly: false,
                    }),
                  reviews_state: z
                    .enum(['initial', 'in_progress', 'approved', 'pending_moderation'])
                    .exactOptional()
                    .openapi({
                      description:
                        'A string that represents Schema Response state. `initial` is the state of a Schema Response on a newly registered Registration, to edit a Schema Response you must create a Schema Response Action that triggers a new submission.',
                      readOnly: false,
                    }),
                  revision_justification: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'A user provided string representing the reason a new Schema Response was needed.',
                      readOnly: false,
                    }),
                  revision_responses: z
                    .object({})
                    .exactOptional()
                    .openapi({
                      description:
                        'A dictionary object representing responses to to the revision where the key is the block key for that the response. For example in the registration response `{"q1": "Answer 1"}` the block key is `q1`..',
                    }),
                  updated_response_keys: z
                    .array(z.any())
                    .exactOptional()
                    .openapi({
                      description:
                        'A list of strings which the response keys for Registration Response Blocks that were updated from the previous schema.',
                      readOnly: true,
                    }),
                })
                .openapi({
                  description: 'The properties of the Schema Response.',
                  readOnly: false,
                  title: 'Attributes',
                  required: [],
                }),
              id: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'The unique identifier of the Schema Response.',
                  readOnly: true,
                }),
              links: z
                .object({
                  self: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'A link to the detail page for a Schema Response.',
                      readOnly: false,
                    }),
                })
                .exactOptional()
                .openapi({
                  description: 'URLs to alternative representations of the Schema Response entity.',
                  readOnly: false,
                  title: 'Links',
                  required: [],
                }),
              relationships: z
                .object({
                  actions: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'A link to the Registration Schema Actions endpoint for this Schema Response.',
                      readOnly: false,
                    }),
                  initiated_by: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'A link to the User who initiated the creation of the Schema Response.',
                      readOnly: false,
                    }),
                  registration: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'A link to the Registration for this Schema Response.',
                      readOnly: false,
                    }),
                  registration_schema: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'A link to the Registration Schema for this Schema Response.',
                      readOnly: false,
                    }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Links to other entities or entity collections that have a relationship to the file entity.',
                  readOnly: false,
                  title: 'Relationships',
                  required: [],
                }),
              type: z
                .string()
                .openapi({
                  description: 'The type identifier of the Schema Response (`schema-response`).',
                  readOnly: false,
                }),
            })
            .openapi({
              example: {
                data: {
                  attributes: {
                    revision_justification: 'I made a mistake.',
                    revision_responses: { Q1: 'updated response' },
                  },
                  type: 'schema-responses',
                },
              },
              required: ['type', 'attributes'],
              title: 'Schema Responses',
            }),
        },
      },
    },
  },
})

