export const getTaxonomiesIndexRoute = createRoute({
  method: 'get',
  path: '/taxonomies/',
  tags: ['Taxonomies'],
  summary: 'List all taxonomies',
  description:
    "\nA paginated list of all [bepress disciplines taxonomies](https://www.bepress.com/wp-content/uploads/2016/12/Digital-Commons-Disciplines-taxonomy-2017-01.pdf).\nNote: this API endpoint is under active development, and is subject to change in the future.\n#### Returns\nReturns a JSON object containing `data` and `links` keys.\n\nThe `data` key contains an array of up to 10 taxonomies. Each resource in the array is a separate taxonomy object.\n\nThe `links` key contains a dictionary of links that can be used for [pagination](#tag/Pagination).\n\nThis request should never return an error.\n#### Filtering\nYou can optionally request that the response only include taxonomies that match your filters by utilizing the `filter` query parameter, e.g. https://api.osf.io/v2/taxonomies/?filter['id']='{taxonomy_id}'.\n\nTaxonomies may be filtered by their `id`, `parents`, and `text`.",
  operationId: 'taxonomies_list',
  responses: {
    200: {
      description: 'OK',
      content: {
        '*/*': {
          schema: z.array(
            z
              .object({
                attributes: z
                  .object({
                    child_count: z
                      .int()
                      .exactOptional()
                      .openapi({
                        description: 'The number of children this taxonomy contains.',
                        readOnly: true,
                      }),
                    parents: z
                      .array(z.string())
                      .exactOptional()
                      .openapi({
                        description:
                          "An array of JSON objects containing keys for `text` (name) and `id` (unique identifier) of this taxonomy's parents",
                        readOnly: true,
                      }),
                    text: z
                      .string()
                      .exactOptional()
                      .openapi({ description: 'The text name of the taxonomy', readOnly: true }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'The properties of the taxonomy entity.',
                    readOnly: true,
                    title: 'Attributes',
                    required: [],
                  }),
                id: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'The identifier of the taxonomy entity.',
                    readOnly: true,
                  }),
                links: z
                  .object({
                    parents: z
                      .array(z.string())
                      .exactOptional()
                      .openapi({
                        description:
                          "An array of links to to this taxonomy's parents. This field is deprecated as of verson 2.4.",
                        readOnly: true,
                      }),
                    self: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A link to the detail page for the taxonomy.',
                        readOnly: true,
                      }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'URLs to alternative representations of the taxonomy entity.',
                    readOnly: true,
                    title: 'Links',
                    required: [],
                  }),
                type: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'The type identifier of the taxonomy entity (`taxonomies`).',
                    readOnly: true,
                  }),
              })
              .openapi({ title: 'Taxonomy', required: [] }),
          ),
        },
      },
    },
  },
})

