export const getUsersIndexRoute = createRoute({
  method: 'get',
  path: '/users/',
  tags: ['Users'],
  summary: 'List all users',
  description:
    "\nA paginated list of all users registered on the OSF. The returned users are sorted by their `date_registered`, with the most recently registered users appearing first.\n\nThe subroute `/users/me/` is a special endpoint that always points to the currently logged-in user.\n#### Versioning\nAs of version `2.3`, merged users will not be returned from this endpoint.\n#### Returns\nReturns a JSON object containing `data` and `links` keys.\n\nThe `data` key contains an array of 10 users. Each resource in the array is a separate users object and contains the full representation of the user, meaning additional requests to a user's detail view are not necessary.\n\nThe `links` key contains a dictionary of links that can be used for [pagination](#tag/Pagination).\n\nThis request should never return an error.\n#### Filtering\nYou can optionally request that the response only include nodes that match your filters by utilizing the `filter` query parameter, e.g. https://api.osf.io/v2/users/?filter[family_name]=Nosek.\n\nUsers may be filtered by their `id`, `full_name`, `given_name`, `middle_name`, or `family_name`.",
  operationId: 'users_list',
  responses: {
    200: {
      description: 'OK',
      content: {
        '*/*': {
          schema: z.array(
            z
              .object({
                attributes: z
                  .object({
                    active: z
                      .boolean()
                      .openapi({
                        description: 'Whether or not the user is an active user.',
                        readOnly: true,
                      }),
                    date_registered: z.iso
                      .datetime({ offset: true })
                      .openapi({
                        description:
                          'The time at which the user registered their account, as an iso8601 formatted timestamp.',
                        readOnly: true,
                      }),
                    family_name: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          'The family name of the user, used for bibliographic citations.',
                        readOnly: false,
                      }),
                    full_name: z
                      .string()
                      .openapi({
                        description: 'The full name of the user, used for display on the OSF.',
                        readOnly: false,
                      }),
                    given_name: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          'The given name of the user, used for bibliographic citations.',
                        readOnly: false,
                      }),
                    locale: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: "The user's locale, e.g. 'en_US'.",
                        readOnly: false,
                      }),
                    middle_names: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          'The middle names of the user, used for bibliographic citations.',
                        readOnly: false,
                      }),
                    suffix: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'The suffix of the user, used for bibliographic citations.',
                        readOnly: false,
                      }),
                    timezone: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: "The user's timezone, e.g. 'Etc/UTC'.",
                        readOnly: false,
                      }),
                  })
                  .openapi({
                    description: 'The properties of the user entity.',
                    readOnly: false,
                    required: ['active', 'date_registered', 'full_name'],
                    title: 'Attributes',
                  }),
                id: z
                  .string()
                  .openapi({
                    description: 'The unique identifier of the user entity.',
                    readOnly: true,
                  }),
                links: z
                  .object({
                    html: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: "A link to the user's profile page on the OSF.",
                        readOnly: true,
                      }),
                    profile_image: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: "A link to the user's profile image.",
                        readOnly: true,
                      }),
                  })
                  .openapi({
                    description: 'URLs to alternative representations of the user entity.',
                    readOnly: true,
                    title: 'Links',
                    required: [],
                  }),
                relationships: z
                  .object({
                    institutions: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          'A link to the list of institutions the user is affiliated with.',
                        readOnly: true,
                      }),
                    nodes: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description: 'A link to the list of nodes the user is a contributor to.',
                        readOnly: true,
                      }),
                  })
                  .openapi({
                    description:
                      'URLs to other entities or entity collections that have a relationship to the user entity.',
                    readOnly: true,
                    title: 'Relationships',
                    required: [],
                  }),
                type: z
                  .string()
                  .openapi({
                    description: 'The type identifier of the user entity (`users`).',
                    readOnly: true,
                  }),
              })
              .openapi({
                example: {
                  data: {
                    attributes: { full_name: 'Casey M. Rollins', middle_names: 'Marie' },
                    id: '{user_id}',
                    type: 'users',
                  },
                },
                required: ['id', 'type', 'attributes', 'relationships', 'links'],
                title: 'User',
              }),
          ),
        },
      },
    },
  },
})

